-- ===========================================================================
-- 20261003010000_about_info.sql
-- ===========================================================================

-- ===========================================================================
-- Settings › About LuyChlat: developer credits, mission and official links,
-- editable by admins (app_settings "about_info"; readable by signed-in users
-- through the existing app_settings select policy). Idempotent.
-- ===========================================================================
create or replace function public.admin_set_about_info(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := coalesce(p_value, '{}'::jsonb);
  link text;
begin
  perform public.require_admin();
  if jsonb_typeof(v) <> 'object' or length(v::text) > 4000 then
    raise exception 'invalid settings' using errcode = '22023';
  end if;
  if char_length(coalesce(v ->> 'developer', '')) > 80
     or char_length(coalesce(v ->> 'credits', '')) > 1000
     or char_length(coalesce(v ->> 'mission_km', '')) > 500
     or char_length(coalesce(v ->> 'mission_en', '')) > 500 then
    raise exception 'text too long' using errcode = '22023';
  end if;
  foreach link in array array[v ->> 'website', v ->> 'facebook'] loop
    if nullif(btrim(link), '') is not null and (link !~ '^https://[^\s"<>]+$' or char_length(link) > 200) then
      raise exception 'links must start with https://' using errcode = '22023';
    end if;
  end loop;
  if nullif(btrim(v ->> 'email'), '') is not null and (v ->> 'email') !~ '^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]+$' then
    raise exception 'invalid email' using errcode = '22023';
  end if;
  insert into public.app_settings (key, value, updated_at) values ('about_info', v, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;
revoke all on function public.admin_set_about_info(jsonb) from public, anon;
grant execute on function public.admin_set_about_info(jsonb) to authenticated;


-- ===========================================================================
-- 20261003020000_brand_luychlat.sql
-- ===========================================================================

-- ===========================================================================
-- Brand: the English name is now "LuyChlat" (Khmer stays លុយឆ្លាត).
-- Several functions sign their Telegram messages "— លុយឆ្លាត · LuySmart";
-- rewrite them in place (same definition, grants and owner) instead of
-- copying their bodies here. Idempotent: once renamed, nothing matches.
-- Internal identifiers (table names, the "luysmart" AI provider value,
-- browser storage keys) are unchanged on purpose.
-- ===========================================================================
do $$
declare
  f record;
begin
  for f in
    select p.oid
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prokind = 'f' and p.prosrc like '%LuySmart%'
  loop
    execute replace(pg_get_functiondef(f.oid), 'LuySmart', 'LuyChlat');
  end loop;
end
$$;


-- ===========================================================================
-- 20261003030000_exchange_rate.sql
-- ===========================================================================

-- ===========================================================================
-- Exchange rate (KHR per 1 USD) saved in the database, per workspace, so it
-- is the same on every device and survives clearing the browser. Before, it
-- lived only in each browser's local storage (and showed the 4,100 default
-- on any device where it was never set).
--
-- null = not set yet: the app uses the default (4,000). set_exchange_rate()
-- applies the user's rate to every workspace they own (Personal, Business,
-- their Family); family members see the owner's rate there.
-- Idempotent: safe to re-run.
-- ===========================================================================
alter table public.workspaces
  add column if not exists khr_per_usd numeric(8, 2);
alter table public.workspaces
  drop constraint if exists workspaces_khr_per_usd_range,
  add constraint workspaces_khr_per_usd_range check (khr_per_usd is null or khr_per_usd between 1000 and 10000);

create or replace function public.set_exchange_rate(p_rate numeric)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  changed integer;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_rate is null or p_rate < 1000 or p_rate > 10000 then
    raise exception 'rate must be between 1000 and 10000' using errcode = '22023';
  end if;
  update public.workspaces set khr_per_usd = round(p_rate) where user_id = uid;
  get diagnostics changed = row_count;
  return changed;
end;
$$;
revoke all on function public.set_exchange_rate(numeric) from public, anon;
grant execute on function public.set_exchange_rate(numeric) to authenticated;


-- ===========================================================================
-- 20261004000000_islamic_finance.sql
-- ===========================================================================

-- ===========================================================================
-- Islamic Finance tools (optional, off by default).
--
-- Settings live in their own table, readable only by the user: whether
-- someone uses these tools is religious information, so it is NOT stored on
-- profiles (family members can read each other's profiles). The flag syncs
-- across the user's devices.
--
-- Turning the tools on adds five categories to the user's own workspaces:
-- Zakat, Sadaqah, Waqf (spending), Bank interest / Riba (income kept out of
-- totals) and Riba purification (its donation, also out of totals). Turning
-- them off keeps all data; the app just hides the tools again.
-- Idempotent: safe to re-run.
-- ===========================================================================

create table if not exists public.islamic_settings (
  user_id         uuid primary key references auth.users (id) on delete cascade,
  enabled         boolean not null default false,
  nisab_basis     text not null default 'GOLD' check (nisab_basis in ('GOLD', 'SILVER')),
  -- Price per gram in USD; null = use the admin default.
  gold_price      numeric(12, 4) check (gold_price is null or gold_price > 0),
  silver_price    numeric(12, 4) check (silver_price is null or silver_price > 0),
  -- Gold the user holds as savings (grams), counted as zakatable wealth.
  gold_grams      numeric(12, 3) not null default 0 check (gold_grams >= 0),
  -- Start of the current lunar year (hawl) for Zakat; due 354 days later.
  hawl_start      date,
  include_receivables boolean not null default false,
  include_business    boolean not null default true,
  updated_at      timestamptz not null default now()
);
alter table public.islamic_settings enable row level security;
drop policy if exists islamic_settings_own on public.islamic_settings;
create policy islamic_settings_own on public.islamic_settings
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Turns the tools on/off for the caller; on also adds the categories to the
-- workspaces the caller owns (Personal, Business, their Family).
create or replace function public.set_islamic_tools(p_enabled boolean)
returns public.islamic_settings
language plpgsql
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  ws record;
  result public.islamic_settings;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  insert into public.islamic_settings (user_id, enabled, updated_at)
  values (uid, coalesce(p_enabled, false), now())
  on conflict (user_id) do update set enabled = excluded.enabled, updated_at = now()
  returning * into result;

  if result.enabled then
    for ws in select id from public.workspaces where user_id = uid loop
      perform public.ensure_preset_category(ws.id, 'zakat', 'EXPENSE', 'hand-heart', '#059669', 'ហ្សាកាត់');
      perform public.ensure_preset_category(ws.id, 'sadaqah', 'EXPENSE', 'hand-heart', '#0d9488', 'ទាន សាដាកះ');
      perform public.ensure_preset_category(ws.id, 'waqf', 'EXPENSE', 'landmark', '#0891b2', 'វ៉ាក់ហ្វ');
      perform public.ensure_preset_category(ws.id, 'riba_purification', 'EXPENSE', 'scale', '#64748b', 'សម្អាតការប្រាក់');
      perform public.ensure_preset_category(ws.id, 'bank_interest', 'INCOME', 'landmark', '#64748b', 'ការប្រាក់ធនាគារ');
    end loop;
  end if;
  return result;
end;
$$;
revoke all on function public.set_islamic_tools(boolean) from public, anon;
grant execute on function public.set_islamic_tools(boolean) to authenticated;

-- ---------------------------------------------------------------------------
-- Admin defaults (app_settings "islamic_defaults"): gold / silver price per
-- gram in USD, and a ±2-day Hijri offset to follow the local moon-sighting
-- announcement (Ramadan / Eid dates).
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_islamic_defaults(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := coalesce(p_value, '{}'::jsonb);
begin
  perform public.require_admin();
  if jsonb_typeof(v) <> 'object' or length(v::text) > 1000 then
    raise exception 'invalid settings' using errcode = '22023';
  end if;
  if (v ? 'gold_price' and v ->> 'gold_price' is not null and not ((v ->> 'gold_price') ~ '^[0-9]+(\.[0-9]+)?$' and (v ->> 'gold_price')::numeric between 0.01 and 100000))
     or (v ? 'silver_price' and v ->> 'silver_price' is not null and not ((v ->> 'silver_price') ~ '^[0-9]+(\.[0-9]+)?$' and (v ->> 'silver_price')::numeric between 0.001 and 10000))
     or (v ? 'hijri_offset' and v ->> 'hijri_offset' is not null and not ((v ->> 'hijri_offset') ~ '^-?[0-2]$')) then
    raise exception 'invalid value' using errcode = '22023';
  end if;
  insert into public.app_settings (key, value, updated_at) values ('islamic_defaults', v, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;
revoke all on function public.admin_set_islamic_defaults(jsonb) from public, anon;
grant execute on function public.admin_set_islamic_defaults(jsonb) to authenticated;


-- ===========================================================================
-- 20261005000000_profiles_business_places.sql
-- ===========================================================================

-- Profile photo / phone / bio, the business profile of a BUSINESS workspace,
-- a private bucket for those images, and a directory of mosques, surau and
-- halal food places (admin-approved). Idempotent.

-- ---------------------------------------------------------------------------
-- Personal profile: photo (storage path), phone and a short bio. Visible to
-- the user and to people they share a workspace with (existing profiles_select).
-- ---------------------------------------------------------------------------
alter table public.profiles add column if not exists avatar_path text;
alter table public.profiles add column if not exists phone text;
alter table public.profiles add column if not exists bio text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_avatar_path_check') then
    alter table public.profiles add constraint profiles_avatar_path_check
      check (avatar_path is null or avatar_path like 'user/' || id::text || '/%');
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profiles_phone_check') then
    alter table public.profiles add constraint profiles_phone_check
      check (phone is null or char_length(phone) <= 30);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profiles_bio_check') then
    alter table public.profiles add constraint profiles_bio_check
      check (bio is null or char_length(bio) <= 200);
  end if;
end $$;

grant update (avatar_path, phone, bio) on public.profiles to authenticated;

-- ---------------------------------------------------------------------------
-- Business profile on the workspace row (the owner edits it; members read it).
-- The business name is the workspace name.
-- ---------------------------------------------------------------------------
alter table public.workspaces add column if not exists logo_path text;
alter table public.workspaces add column if not exists business_phone text;
alter table public.workspaces add column if not exists business_address text;
alter table public.workspaces add column if not exists business_industry text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'workspaces_logo_path_check') then
    alter table public.workspaces add constraint workspaces_logo_path_check
      check (logo_path is null or logo_path like 'ws/' || id::text || '/%');
  end if;
  if not exists (select 1 from pg_constraint where conname = 'workspaces_business_fields_check') then
    alter table public.workspaces add constraint workspaces_business_fields_check
      check (
        (business_phone is null or char_length(business_phone) <= 30)
        and (business_address is null or char_length(business_address) <= 200)
        and (business_industry is null or char_length(business_industry) <= 60)
      );
  end if;
end $$;

grant update (logo_path, business_phone, business_address, business_industry) on public.workspaces to authenticated;

-- ---------------------------------------------------------------------------
-- Images: private bucket, shown through short-lived signed URLs.
--   user/<user id>/<file>      personal photo: the user writes; people who
--                              share a workspace with them may view
--   ws/<workspace id>/<file>   business logo: the owner writes; members view
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('profile-images', 'profile-images', false, 1048576, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

create or replace function public.profile_image_access(p_name text, p_write boolean)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  parts text[] := string_to_array(p_name, '/');
  uid uuid := auth.uid();
  target uuid;
begin
  if uid is null or array_length(parts, 1) <> 3 or parts[2] !~ '^[0-9a-f-]{36}$' then
    return false;
  end if;
  target := parts[2]::uuid;
  if parts[1] = 'user' then
    return target = uid or (not p_write and public.shares_workspace_with(target));
  elsif parts[1] = 'ws' then
    if p_write then
      return exists (select 1 from public.workspaces w where w.id = target and w.user_id = uid and w.type = 'BUSINESS');
    end if;
    return public.is_workspace_member(target);
  end if;
  return false;
end;
$$;
revoke all on function public.profile_image_access(text, boolean) from public, anon;
grant execute on function public.profile_image_access(text, boolean) to authenticated;

drop policy if exists profile_images_select on storage.objects;
create policy profile_images_select on storage.objects
  for select to authenticated using (bucket_id = 'profile-images' and public.profile_image_access(name, false));
drop policy if exists profile_images_insert on storage.objects;
create policy profile_images_insert on storage.objects
  for insert to authenticated with check (bucket_id = 'profile-images' and public.profile_image_access(name, true));
drop policy if exists profile_images_update on storage.objects;
create policy profile_images_update on storage.objects
  for update to authenticated
  using (bucket_id = 'profile-images' and public.profile_image_access(name, true))
  with check (bucket_id = 'profile-images' and public.profile_image_access(name, true));
drop policy if exists profile_images_delete on storage.objects;
create policy profile_images_delete on storage.objects
  for delete to authenticated using (bucket_id = 'profile-images' and public.profile_image_access(name, true));

-- ---------------------------------------------------------------------------
-- Mosques, surau and halal food places. Signed-in users may suggest a place;
-- it is listed for everyone only after an admin approves it. Only admins can
-- mark a place as halal-certified.
-- ---------------------------------------------------------------------------
create table if not exists public.islamic_places (
  id              uuid primary key default gen_random_uuid(),
  kind            text not null check (kind in ('MOSQUE', 'SURAU', 'HALAL')),
  name            text not null check (char_length(btrim(name)) between 1 and 120),
  province        text check (province is null or char_length(province) <= 40),
  address         text check (address is null or char_length(address) <= 300),
  lat             double precision check (lat is null or lat between -90 and 90),
  lng             double precision check (lng is null or lng between -180 and 180),
  phone           text check (phone is null or char_length(phone) <= 30),
  note            text check (note is null or char_length(note) <= 300),
  halal_certified boolean not null default false,
  approved        boolean not null default false,
  created_by      uuid default auth.uid() references auth.users (id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists islamic_places_approved_idx on public.islamic_places (approved, kind);
alter table public.islamic_places enable row level security;

drop policy if exists islamic_places_select on public.islamic_places;
create policy islamic_places_select on public.islamic_places
  for select to authenticated
  using (approved or created_by = (select auth.uid()) or public.is_admin());
drop policy if exists islamic_places_insert on public.islamic_places;
create policy islamic_places_insert on public.islamic_places
  for insert to authenticated
  with check (
    public.is_admin()
    or (created_by = (select auth.uid()) and not approved and not halal_certified)
  );
drop policy if exists islamic_places_update on public.islamic_places;
create policy islamic_places_update on public.islamic_places
  for update to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists islamic_places_delete on public.islamic_places;
create policy islamic_places_delete on public.islamic_places
  for delete to authenticated
  using (public.is_admin() or (created_by = (select auth.uid()) and not approved));

grant select, insert, update, delete on public.islamic_places to authenticated;

-- At most 10 suggestions waiting for review per person (keeps the queue clean).
create or replace function public.limit_place_suggestions()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not new.approved and not public.is_admin()
     and (select count(*) from public.islamic_places p where p.created_by = new.created_by and not p.approved) >= 10 then
    raise exception 'too many pending suggestions' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
drop trigger if exists islamic_places_limit on public.islamic_places;
create trigger islamic_places_limit
  before insert on public.islamic_places
  for each row execute function public.limit_place_suggestions();


-- ===========================================================================
-- 20261006000000_debt_insurance_savings_goals.sql
-- ===========================================================================

-- Loan insurance on debts, and savings goals. Idempotent.

-- ---------------------------------------------------------------------------
-- Debts: optional loan insurance (e.g. credit life required by the bank).
-- ---------------------------------------------------------------------------
alter table public.debts add column if not exists insured boolean not null default false;
alter table public.debts add column if not exists insurer text;
alter table public.debts add column if not exists insurance_policy_no text;
alter table public.debts add column if not exists insurance_premium numeric(18, 2);
alter table public.debts add column if not exists insurance_currency public.currency_code;
alter table public.debts add column if not exists insurance_renewal_date date;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'debts_insurance_check') then
    alter table public.debts add constraint debts_insurance_check
      check (
        (insurer is null or char_length(insurer) <= 60)
        and (insurance_policy_no is null or char_length(insurance_policy_no) <= 60)
        and (insurance_premium is null or insurance_premium >= 0)
      );
  end if;
end $$;

grant update (insured, insurer, insurance_policy_no, insurance_premium, insurance_currency, insurance_renewal_date)
  on public.debts to authenticated;

-- ---------------------------------------------------------------------------
-- Savings goals: a goal is a savings pot (a wallet with a target). Money gets
-- in and out only by transfers from/to the user's other wallets, so net worth
-- never changes when saving; a goal starts empty.
-- ---------------------------------------------------------------------------
alter table public.wallets_accounts add column if not exists goal_target numeric(18, 2);
alter table public.wallets_accounts add column if not exists goal_date date;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'wallets_goal_target_check') then
    alter table public.wallets_accounts add constraint wallets_goal_target_check
      check (goal_target is null or goal_target > 0);
  end if;
end $$;

create index if not exists wallets_accounts_goals_idx on public.wallets_accounts (workspace_id) where goal_target is not null;

grant update (goal_target, goal_date) on public.wallets_accounts to authenticated;

create or replace function public.guard_goal_wallet()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if coalesce(current_setting('luysmart.import', true), '') = 'on' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.goal_target is not null and new.balance <> 0 then
      raise exception 'goal_starts_empty' using errcode = 'P0001';
    end if;
  elsif (old.goal_target is null) <> (new.goal_target is null) then
    -- A wallet can't become a goal (or back): its history would stop adding up.
    raise exception 'goal_kind_locked' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

drop trigger if exists wallets_accounts_goal_guard on public.wallets_accounts;
create trigger wallets_accounts_goal_guard
  before insert or update of goal_target on public.wallets_accounts
  for each row execute function public.guard_goal_wallet();

-- Income and expenses can't be booked on a goal: only transfers move money in or out.
create or replace function public.guard_goal_transactions()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.type <> 'TRANSFER'
     and exists (select 1 from public.wallets_accounts w where w.id = new.wallet_id and w.goal_target is not null) then
    raise exception 'goal_transfers_only' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

drop trigger if exists transactions_goal_guard on public.transactions;
create trigger transactions_goal_guard
  before insert or update of type, wallet_id on public.transactions
  for each row execute function public.guard_goal_transactions();

-- The plan's wallet limit doesn't count savings goals.
create or replace function public.guard_wallet_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  owner uuid;
  max_wallets integer;
  used integer;
begin
  if (select auth.uid()) is null or coalesce(current_setting('luysmart.import', true), '') = 'on' then
    return new;
  end if;
  -- Only creating a wallet or bringing one back from the archive counts.
  if tg_op = 'UPDATE' and not (old.archived_at is not null and new.archived_at is null) then
    return new;
  end if;
  if new.archived_at is not null or new.goal_target is not null then
    return new;
  end if;
  select user_id into owner from public.workspaces where id = new.workspace_id;
  max_wallets := (public.plan_of(owner)).max_wallets;
  if max_wallets is null then
    return new;
  end if;
  select count(*) into used
  from public.wallets_accounts w join public.workspaces ws on ws.id = w.workspace_id
  where ws.user_id = owner and w.archived_at is null and w.goal_target is null and w.id <> new.id;
  if used >= max_wallets then
    raise exception 'plan_limit:wallets' using errcode = 'P0001', hint = max_wallets::text;
  end if;
  return new;
end;
$$;


-- ===========================================================================
-- 20261007000000_ultra_business_trial.sql
-- ===========================================================================

-- Free / Pro / Ultra. Idempotent.
--   Free  : Personal + one Business workspace on a 90-day trial (read-only after)
--   Pro   : Personal + one Business workspace
--   Ultra : Personal + any number of Business workspaces
-- A Business workspace beyond the plan's allowance, or a Free one after its
-- trial, stays readable (and exportable) but can't be changed. Nothing is
-- deleted when a plan ends.

-- ---------------------------------------------------------------------------
-- Plans
-- ---------------------------------------------------------------------------
alter table public.plans drop constraint if exists plans_tier_check;
alter table public.plans add constraint plans_tier_check check (tier in ('FREE', 'PRO', 'ULTRA'));
-- null = unlimited
alter table public.plans add column if not exists max_business_workspaces integer;
alter table public.plans add column if not exists business_trial_days integer not null default 0;

update public.plans set max_business_workspaces = 1, business_trial_days = 90 where code = 'FREE';
update public.plans set max_business_workspaces = 1, business_trial_days = 0, price_usd = 2.99, price_khr = 12000 where code = 'PRO_MONTHLY';
update public.plans set max_business_workspaces = 1, business_trial_days = 0, price_usd = 24.99, price_khr = 100000 where code = 'PRO_YEARLY';

insert into public.plans (code, tier, name, price_usd, price_khr, period_days, max_wallets, max_family_members, ai_queries_per_month, can_export, can_credit_score, sort_order, max_business_workspaces, business_trial_days)
values
  ('ULTRA_MONTHLY', 'ULTRA', 'Ultra Monthly', 6.99,  28000,  30,  null, null, 100, true, true, 3, null, 0),
  ('ULTRA_YEARLY',  'ULTRA', 'Ultra Yearly',  59.99, 240000, 365, null, null, 100, true, true, 4, null, 0)
on conflict (code) do nothing;

-- ---------------------------------------------------------------------------
-- Paid = PRO or ULTRA. Rewrites the current definitions of every function that
-- still treats 'PRO' as the only paid tier (request, grant, admin list, …).
-- ---------------------------------------------------------------------------
do $$
declare
  f record;
  def text;
begin
  for f in
    select p.oid
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and (p.prosrc like '%tier = ''PRO''%' or p.prosrc like '%then ''PRO'' else ''FREE''%')
  loop
    def := pg_get_functiondef(f.oid);
    def := replace(def, 'tier = ''PRO''', 'tier in (''PRO'', ''ULTRA'')');
    -- Admin user list: show the real tier of an active plan.
    def := replace(def, 'then ''PRO'' else ''FREE''', 'then (select pl.tier from public.plans pl where pl.code = s.plan_code) else ''FREE''');
    execute def;
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Business trial: counted from the business workspace's trial start. Existing
-- workspaces start their 90 days now, so nobody's trial is already over.
-- ---------------------------------------------------------------------------
do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'workspaces' and column_name = 'trial_started_at'
  ) then
    alter table public.workspaces add column trial_started_at timestamptz not null default now();
  end if;
end $$;

-- Whether the owner's plan lets this workspace be changed, and why not.
--   reason: null (allowed) | 'TRIAL_ENDED' | 'PLAN_LIMIT'
create or replace function public.workspace_plan_access(p_workspace_id uuid, out writable boolean, out reason text, out trial_ends_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  w public.workspaces;
  p public.plans;
  business_rank integer;
begin
  writable := true;
  select * into w from public.workspaces where id = p_workspace_id;
  if not found or w.type <> 'BUSINESS' then
    return;
  end if;
  p := public.plan_of(w.user_id);
  -- 1 = the owner's first business workspace.
  select count(*) + 1 into business_rank
  from public.workspaces o
  where o.user_id = w.user_id and o.type = 'BUSINESS' and (o.created_at, o.id) < (w.created_at, w.id);
  if p.max_business_workspaces is not null and business_rank > p.max_business_workspaces then
    writable := false;
    reason := 'PLAN_LIMIT';
    return;
  end if;
  if p.tier = 'FREE' then
    trial_ends_at := w.trial_started_at + make_interval(days => p.business_trial_days);
    if now() >= trial_ends_at then
      writable := false;
      reason := 'TRIAL_ENDED';
    end if;
  end if;
end;
$$;
revoke all on function public.workspace_plan_access(uuid) from public, anon;
grant execute on function public.workspace_plan_access(uuid) to authenticated;

-- Every write check (RLS and RPCs) goes through here: role AND plan.
create or replace function public.can_write_workspace(ws_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.workspace_members m
    where m.workspace_id = ws_id and m.user_id = (select auth.uid()) and m.role in ('OWNER', 'MEMBER')
  ) and (public.workspace_plan_access(ws_id)).writable;
$$;

-- Plan access of each workspace the caller belongs to (for the app's notices).
create or replace function public.my_workspace_access()
returns table (workspace_id uuid, writable boolean, reason text, trial_ends_at timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select m.workspace_id, a.writable, a.reason, a.trial_ends_at
  from public.workspace_members m
  cross join lateral public.workspace_plan_access(m.workspace_id) a
  where m.user_id = (select auth.uid());
$$;
revoke all on function public.my_workspace_access() from public, anon;
grant execute on function public.my_workspace_access() to authenticated;

-- ---------------------------------------------------------------------------
-- One Personal workspace per user (one owned Family is enforced by
-- create_family_workspace); Business workspaces are limited by the plan
-- instead (create_business_workspace).
-- ---------------------------------------------------------------------------
alter table public.workspaces drop constraint if exists workspaces_user_id_type_key;
create unique index if not exists workspaces_one_personal_idx on public.workspaces (user_id) where type = 'PERSONAL';

-- ---------------------------------------------------------------------------
-- Ultra: add more business workspaces.
-- ---------------------------------------------------------------------------
create or replace function public.create_business_workspace(p_name text)
returns public.workspaces
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  p public.plans;
  owned integer;
  result public.workspaces;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  p := public.plan_of(uid);
  select count(*) into owned from public.workspaces where user_id = uid and type = 'BUSINESS';
  if p.max_business_workspaces is not null and owned >= p.max_business_workspaces then
    raise exception 'plan_limit:business' using errcode = 'P0001', hint = p.max_business_workspaces::text;
  end if;
  insert into public.workspaces (user_id, name, type)
  values (uid, coalesce(nullif(left(btrim(p_name), 60), ''), 'អាជីវកម្ម'), 'BUSINESS')
  returning * into result;
  perform public.seed_default_categories(result.id, 'BUSINESS');
  return result;
end;
$$;
revoke all on function public.create_business_workspace(text) from public, anon;
grant execute on function public.create_business_workspace(text) to authenticated;

-- ---------------------------------------------------------------------------
-- my_plan: business allowance and the trial end of the first business.
-- ---------------------------------------------------------------------------
create or replace function public.my_plan()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  p public.plans;
  s public.subscriptions;
  used integer;
  first_business uuid;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  p := public.plan_of(uid);
  select * into s from public.subscriptions where user_id = uid;
  select coalesce((select ai_queries from public.usage_counters where user_id = uid and month = public.current_ai_month()), 0) into used;
  select id into first_business from public.workspaces where user_id = uid and type = 'BUSINESS' order by created_at, id limit 1;
  return jsonb_build_object(
    'tier', p.tier,
    'plan_code', p.code,
    'period_end', case when p.tier <> 'FREE' then s.current_period_end end,
    'last_plan_code', s.plan_code,
    'last_period_end', s.current_period_end,
    'max_wallets', p.max_wallets,
    'max_family_members', p.max_family_members,
    'max_business_workspaces', p.max_business_workspaces,
    'business_trial_ends_at', case when p.tier = 'FREE' and first_business is not null then (public.workspace_plan_access(first_business)).trial_ends_at end,
    'ai_queries_per_month', p.ai_queries_per_month,
    'ai_queries_used', used,
    'can_export', p.can_export,
    'can_credit_score', p.can_credit_score,
    'is_admin', public.is_admin()
  );
end;
$$;


-- ===========================================================================
-- 20261008000000_assets_gold.sql
-- ===========================================================================

-- Assets: gold & platinum holdings (Cambodian weight units, daily market
-- rates set by admins) and physical assets (land, house, vehicles…). Idempotent.
--
-- Weight is stored in ហ៊ុន (hun), the smallest everyday unit:
--   1 តម្លឹង (damlung) = 10 ជី (chi) = 100 ហ៊ុន = 37.5 g;  1 ហ៊ុន = 0.375 g.

create table if not exists public.gold_holdings (
  id                uuid primary key default gen_random_uuid(),
  workspace_id      uuid not null references public.workspaces (id) on delete cascade,
  name              text not null check (char_length(btrim(name)) between 1 and 80),
  -- GOLD_BAR = មាសគីឡូ (99.99%), GOLD_24K = មាសទឹក១០, GOLD_18K = មាសទឹក៨, PLATINUM = ប្លាទីន
  kind              text not null check (kind in ('GOLD_BAR', 'GOLD_24K', 'GOLD_18K', 'PLATINUM')),
  weight_hun        numeric(12, 2) not null check (weight_hun > 0 and weight_hun <= 1000000),
  purchase_date     date,
  purchase_price    numeric(18, 2) check (purchase_price is null or purchase_price >= 0),
  purchase_currency public.currency_code,
  note              text check (note is null or char_length(note) <= 300),
  created_by        uuid default auth.uid() references auth.users (id) on delete set null,
  created_at        timestamptz not null default now(),
  check ((purchase_price is null) = (purchase_currency is null))
);
create index if not exists gold_holdings_workspace_idx on public.gold_holdings (workspace_id);
alter table public.gold_holdings enable row level security;

-- Same rules as the rest of a workspace: members read; owners/members write
-- (which also respects the plan's read-only business workspaces).
drop policy if exists gold_holdings_select on public.gold_holdings;
create policy gold_holdings_select on public.gold_holdings
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists gold_holdings_insert on public.gold_holdings;
create policy gold_holdings_insert on public.gold_holdings
  for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists gold_holdings_update on public.gold_holdings;
create policy gold_holdings_update on public.gold_holdings
  for update to authenticated
  using (public.can_write_workspace(workspace_id))
  with check (public.can_write_workspace(workspace_id));
drop policy if exists gold_holdings_delete on public.gold_holdings;
create policy gold_holdings_delete on public.gold_holdings
  for delete to authenticated using (public.can_write_workspace(workspace_id));

grant select, insert, delete on public.gold_holdings to authenticated;
grant update (name, kind, weight_hun, purchase_date, purchase_price, purchase_currency, note) on public.gold_holdings to authenticated;

-- ---------------------------------------------------------------------------
-- Market rates (app_settings "gold_rates"): USD per damlung for each kind,
-- e.g. {"GOLD_BAR": "2850", "GOLD_24K": "2800", "GOLD_18K": "2050", "PLATINUM": "1150"}.
-- Readable by every signed-in user (existing app_settings policy).
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_gold_rates(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := coalesce(p_value, '{}'::jsonb);
  k text;
begin
  perform public.require_admin();
  if jsonb_typeof(v) <> 'object' or length(v::text) > 500 then
    raise exception 'invalid rates' using errcode = '22023';
  end if;
  for k in select jsonb_object_keys(v) loop
    if k not in ('GOLD_BAR', 'GOLD_24K', 'GOLD_18K', 'PLATINUM') then
      raise exception 'unknown kind %', k using errcode = '22023';
    end if;
    if v ->> k is not null and not ((v ->> k) ~ '^[0-9]+(\.[0-9]+)?$' and (v ->> k)::numeric between 1 and 1000000) then
      raise exception 'invalid rate for %', k using errcode = '22023';
    end if;
  end loop;
  insert into public.app_settings (key, value, updated_at) values ('gold_rates', v, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;
revoke all on function public.admin_set_gold_rates(jsonb) from public, anon;
grant execute on function public.admin_set_gold_rates(jsonb) to authenticated;

-- "Reset all data" also removes gold holdings (in place, keeping the rest of
-- the latest reset_my_data definition).
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.reset_my_data()'::regprocedure);
  if position('gold_holdings' in def) = 0 then
    def := replace(
      def,
      'delete from public.wallets_accounts where workspace_id in (select id from reset_ws);',
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);
  delete from public.wallets_accounts where workspace_id in (select id from reset_ws);'
    );
    execute def;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Real estate, vehicles, machinery and other physical assets: an estimated
-- market value, optionally linked to the bank loan that financed it (net
-- equity = value − what is still owed on that loan).
-- ---------------------------------------------------------------------------
create table if not exists public.physical_assets (
  id              uuid primary key default gen_random_uuid(),
  workspace_id    uuid not null references public.workspaces (id) on delete cascade,
  kind            text not null check (kind in ('LAND', 'HOUSE', 'VEHICLE', 'MACHINERY', 'OTHER')),
  name            text not null check (char_length(btrim(name)) between 1 and 80),
  estimated_value numeric(18, 2) not null check (estimated_value >= 0),
  currency        public.currency_code not null,
  purchase_date   date,
  purchase_price  numeric(18, 2) check (purchase_price is null or purchase_price >= 0),
  debt_id         uuid,
  note            text check (note is null or char_length(note) <= 300),
  created_by      uuid default auth.uid() references auth.users (id) on delete set null,
  created_at      timestamptz not null default now(),
  -- The loan must be in the same workspace; deleting it just removes the link.
  foreign key (debt_id, workspace_id) references public.debts (id, workspace_id) on delete set null (debt_id)
);
create index if not exists physical_assets_workspace_idx on public.physical_assets (workspace_id);
alter table public.physical_assets enable row level security;

drop policy if exists physical_assets_select on public.physical_assets;
create policy physical_assets_select on public.physical_assets
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists physical_assets_insert on public.physical_assets;
create policy physical_assets_insert on public.physical_assets
  for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists physical_assets_update on public.physical_assets;
create policy physical_assets_update on public.physical_assets
  for update to authenticated
  using (public.can_write_workspace(workspace_id))
  with check (public.can_write_workspace(workspace_id));
drop policy if exists physical_assets_delete on public.physical_assets;
create policy physical_assets_delete on public.physical_assets
  for delete to authenticated using (public.can_write_workspace(workspace_id));

grant select, insert, delete on public.physical_assets to authenticated;
grant update (kind, name, estimated_value, currency, purchase_date, purchase_price, debt_id, note) on public.physical_assets to authenticated;

do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.reset_my_data()'::regprocedure);
  if position('physical_assets' in def) = 0 then
    def := replace(
      def,
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);',
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);
  delete from public.physical_assets where workspace_id in (select id from reset_ws);'
    );
    execute def;
  end if;
end $$;


-- ===========================================================================
-- 20261009000000_business_archive.sql
-- ===========================================================================

-- Closed businesses: archive (hidden, read-only, restorable) or delete
-- permanently. At least one active Business workspace always remains, and
-- archived ones don't count toward the plan's business allowance. Idempotent.

alter table public.workspaces add column if not exists archived_at timestamptz;

create or replace function public.workspace_plan_access(p_workspace_id uuid, out writable boolean, out reason text, out trial_ends_at timestamptz)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  w public.workspaces;
  p public.plans;
  business_rank integer;
begin
  writable := true;
  select * into w from public.workspaces where id = p_workspace_id;
  if not found or w.type <> 'BUSINESS' then
    return;
  end if;
  if w.archived_at is not null then
    writable := false;
    reason := 'ARCHIVED';
    return;
  end if;
  p := public.plan_of(w.user_id);
  -- 1 = the owner's first active business workspace.
  select count(*) + 1 into business_rank
  from public.workspaces o
  where o.user_id = w.user_id and o.type = 'BUSINESS' and o.archived_at is null and (o.created_at, o.id) < (w.created_at, w.id);
  if p.max_business_workspaces is not null and business_rank > p.max_business_workspaces then
    writable := false;
    reason := 'PLAN_LIMIT';
    return;
  end if;
  if p.tier = 'FREE' then
    trial_ends_at := w.trial_started_at + make_interval(days => p.business_trial_days);
    if now() >= trial_ends_at then
      writable := false;
      reason := 'TRIAL_ENDED';
    end if;
  end if;
end;
$$;

create or replace function public.create_business_workspace(p_name text)
returns public.workspaces
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  p public.plans;
  owned integer;
  result public.workspaces;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  p := public.plan_of(uid);
  select count(*) into owned from public.workspaces where user_id = uid and type = 'BUSINESS' and archived_at is null;
  if p.max_business_workspaces is not null and owned >= p.max_business_workspaces then
    raise exception 'plan_limit:business' using errcode = 'P0001', hint = p.max_business_workspaces::text;
  end if;
  insert into public.workspaces (user_id, name, type)
  values (uid, coalesce(nullif(left(btrim(p_name), 60), ''), 'អាជីវកម្ម'), 'BUSINESS')
  returning * into result;
  perform public.seed_default_categories(result.id, 'BUSINESS');
  return result;
end;
$$;

-- Owner only; never the last active business.
create or replace function public.set_business_archived(p_workspace_id uuid, p_archived boolean)
returns public.workspaces
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  result public.workspaces;
begin
  if not exists (select 1 from public.workspaces where id = p_workspace_id and user_id = uid and type = 'BUSINESS') then
    raise exception 'only the owner can archive this business' using errcode = '42501';
  end if;
  if p_archived and not exists (
    select 1 from public.workspaces
    where user_id = uid and type = 'BUSINESS' and archived_at is null and id <> p_workspace_id
  ) then
    raise exception 'last_business' using errcode = 'P0001';
  end if;
  update public.workspaces set archived_at = case when p_archived then coalesce(archived_at, now()) end
  where id = p_workspace_id
  returning * into result;
  return result;
end;
$$;
revoke all on function public.set_business_archived(uuid, boolean) from public, anon;
grant execute on function public.set_business_archived(uuid, boolean) to authenticated;

-- Deletes a business and everything in it. Owner only; never the last active business.
create or replace function public.delete_business_workspace(p_workspace_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
begin
  if not exists (select 1 from public.workspaces where id = p_workspace_id and user_id = uid and type = 'BUSINESS') then
    raise exception 'only the owner can delete this business' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.workspaces
    where user_id = uid and type = 'BUSINESS' and archived_at is null and id <> p_workspace_id
  ) then
    raise exception 'last_business' using errcode = 'P0001';
  end if;
  perform set_config('luysmart.system', 'on', true);
  -- Ledger first (cascades repayments), then debts: wallets are referenced
  -- with NO ACTION, which a single cascading delete would trip over.
  delete from public.transactions where workspace_id = p_workspace_id;
  delete from public.debts where workspace_id = p_workspace_id;
  delete from public.workspaces where id = p_workspace_id;
  perform set_config('luysmart.system', '', true);
end;
$$;
revoke all on function public.delete_business_workspace(uuid) from public, anon;
grant execute on function public.delete_business_workspace(uuid) to authenticated;


-- ===========================================================================
-- 20261010000000_investments.sql
-- ===========================================================================

-- Stocks (CSX and international) and crypto holdings, and daily market
-- prices set by admins. Idempotent.
--
-- A holding stores the quantity, the average buy price per unit and, when the
-- admin hasn't priced its symbol, the user's own latest price.

create table if not exists public.investment_holdings (
  id               uuid primary key default gen_random_uuid(),
  workspace_id     uuid not null references public.workspaces (id) on delete cascade,
  -- STOCK_CSX (Cambodia Securities Exchange), STOCK_INTL (e.g. AAPL), CRYPTO (e.g. BTC)
  market           text not null check (market in ('STOCK_CSX', 'STOCK_INTL', 'CRYPTO')),
  symbol           text not null check (symbol ~ '^[A-Z0-9.\-]{1,15}$'),
  name             text check (name is null or char_length(name) <= 80),
  quantity         numeric(28, 8) not null check (quantity > 0),
  avg_cost         numeric(24, 8) not null check (avg_cost >= 0),
  currency         public.currency_code not null,
  current_price    numeric(24, 8) check (current_price is null or current_price >= 0),
  price_updated_at timestamptz,
  created_by       uuid default auth.uid() references auth.users (id) on delete set null,
  created_at       timestamptz not null default now(),
  -- Crypto is quoted in US dollars.
  check (market <> 'CRYPTO' or currency = 'USD')
);
create index if not exists investment_holdings_workspace_idx on public.investment_holdings (workspace_id);
alter table public.investment_holdings enable row level security;

drop policy if exists investment_holdings_select on public.investment_holdings;
create policy investment_holdings_select on public.investment_holdings
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists investment_holdings_insert on public.investment_holdings;
create policy investment_holdings_insert on public.investment_holdings
  for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists investment_holdings_update on public.investment_holdings;
create policy investment_holdings_update on public.investment_holdings
  for update to authenticated
  using (public.can_write_workspace(workspace_id))
  with check (public.can_write_workspace(workspace_id));
drop policy if exists investment_holdings_delete on public.investment_holdings;
create policy investment_holdings_delete on public.investment_holdings
  for delete to authenticated using (public.can_write_workspace(workspace_id));

grant select, insert, delete on public.investment_holdings to authenticated;
grant update (market, symbol, name, quantity, avg_cost, currency, current_price, price_updated_at) on public.investment_holdings to authenticated;

-- ---------------------------------------------------------------------------
-- Market prices (app_settings "market_prices"), keyed "<market>:<symbol>":
--   {"STOCK_CSX:ABC": "7020", "CRYPTO:BTC": "65000", "STOCK_INTL:AAPL": "190.5"}
-- CSX prices are in riel, the others in US dollars. Admin prices win over a
-- user's own price for the same symbol.
-- ---------------------------------------------------------------------------
create or replace function public.admin_set_market_prices(p_value jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v jsonb := coalesce(p_value, '{}'::jsonb);
  k text;
begin
  perform public.require_admin();
  if jsonb_typeof(v) <> 'object' or length(v::text) > 20000 then
    raise exception 'invalid prices' using errcode = '22023';
  end if;
  for k in select jsonb_object_keys(v) loop
    if k !~ '^(STOCK_CSX|STOCK_INTL|CRYPTO):[A-Z0-9.\-]{1,15}$' then
      raise exception 'invalid symbol %', k using errcode = '22023';
    end if;
    if v ->> k is null or not ((v ->> k) ~ '^[0-9]+(\.[0-9]+)?$' and (v ->> k)::numeric between 0 and 1000000000) then
      raise exception 'invalid price for %', k using errcode = '22023';
    end if;
  end loop;
  insert into public.app_settings (key, value, updated_at) values ('market_prices', v, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;
revoke all on function public.admin_set_market_prices(jsonb) from public, anon;
grant execute on function public.admin_set_market_prices(jsonb) to authenticated;

-- "Reset all data" also removes investment holdings.
do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.reset_my_data()'::regprocedure);
  if position('investment_holdings' in def) = 0 then
    def := replace(
      def,
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);',
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);
  delete from public.investment_holdings where workspace_id in (select id from reset_ws);'
    );
    execute def;
  end if;
end $$;


-- ===========================================================================
-- 20261011000000_diamonds.sql
-- ===========================================================================

-- Diamonds (ពេជ្រ) in the jewelry section: Cambodian and GIA grading,
-- certificate, and the shop's buy-back deduction, from which the app works
-- out the liquid resale value used in net worth. Idempotent.

create table if not exists public.diamond_holdings (
  id              uuid primary key default gen_random_uuid(),
  workspace_id    uuid not null references public.workspaces (id) on delete cascade,
  name            text not null check (char_length(btrim(name)) between 1 and 80),
  form            text not null check (form in ('RING', 'NECKLACE', 'EARRINGS', 'BRACELET', 'LOOSE')),
  -- Size in លី = millimetres (diameter of a round stone), e.g. 5.4.
  size_li         numeric(5, 2) check (size_li is null or size_li between 0.5 and 50),
  carat           numeric(7, 3) check (carat is null or carat between 0.001 and 500),
  -- KH = Cambodian water scale (ទឹក 97–100), GIA = D…M
  color_scale     text check (color_scale in ('KH', 'GIA')),
  color           text check (color is null or color in ('97', '98', '99', '100', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L', 'M')),
  clarity         text check (clarity is null or clarity in ('FL', 'IF', 'VVS1', 'VVS2', 'VS1', 'VS2', 'SI1', 'SI2', 'I1')),
  cert_type       text not null default 'NONE' check (cert_type in ('GIA', 'HRD', 'IGI', 'STORE', 'NONE')),
  cert_number     text check (cert_number is null or char_length(cert_number) <= 60),
  store           text check (store is null or char_length(store) <= 80),
  purchase_date   date,
  purchase_price  numeric(18, 2) not null check (purchase_price >= 0),
  currency        public.currency_code not null default 'USD',
  -- Shop buy-back: % taken off the purchase price when selling back for cash (and when trading in).
  buyback_pct     numeric(5, 2) not null default 15 check (buyback_pct between 0 and 100),
  tradein_pct     numeric(5, 2) check (tradein_pct is null or tradein_pct between 0 and 100),
  note            text check (note is null or char_length(note) <= 300),
  created_by      uuid default auth.uid() references auth.users (id) on delete set null,
  created_at      timestamptz not null default now(),
  check ((color is null) or (color_scale = 'KH' and color in ('97', '98', '99', '100')) or (color_scale = 'GIA' and color !~ '^[0-9]'))
);
create index if not exists diamond_holdings_workspace_idx on public.diamond_holdings (workspace_id);
alter table public.diamond_holdings enable row level security;

drop policy if exists diamond_holdings_select on public.diamond_holdings;
create policy diamond_holdings_select on public.diamond_holdings
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists diamond_holdings_insert on public.diamond_holdings;
create policy diamond_holdings_insert on public.diamond_holdings
  for insert to authenticated with check (public.can_write_workspace(workspace_id));
drop policy if exists diamond_holdings_update on public.diamond_holdings;
create policy diamond_holdings_update on public.diamond_holdings
  for update to authenticated
  using (public.can_write_workspace(workspace_id))
  with check (public.can_write_workspace(workspace_id));
drop policy if exists diamond_holdings_delete on public.diamond_holdings;
create policy diamond_holdings_delete on public.diamond_holdings
  for delete to authenticated using (public.can_write_workspace(workspace_id));

grant select, insert, delete on public.diamond_holdings to authenticated;
grant update (name, form, size_li, carat, color_scale, color, clarity, cert_type, cert_number, store, purchase_date, purchase_price, currency, buyback_pct, tradein_pct, note)
  on public.diamond_holdings to authenticated;

do $$
declare
  def text;
begin
  def := pg_get_functiondef('public.reset_my_data()'::regprocedure);
  if position('diamond_holdings' in def) = 0 then
    def := replace(
      def,
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);',
      'delete from public.gold_holdings where workspace_id in (select id from reset_ws);
  delete from public.diamond_holdings where workspace_id in (select id from reset_ws);'
    );
    execute def;
  end if;
end $$;
